/* --- 1. 强制方角与全局重置 --- */
.xt-root {
    --xt-bg: #ffffff !important;
    --xt-radius: 0px !important;
    --xt-radius-sm: 0px !important;
    border-radius: 0px !important;
    padding: 0 !important;
    margin: 0 !important;
    box-shadow: none !important;
    background: #ffffff !important;
    font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif !important;
}
.xt-text { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; font-style: normal !important; }

/* --- 2. 顶栏导航 --- */
.xt-text-topNav {
    text-align: center !important; font-size: 17px !important; font-weight: 600 !important; color: #333 !important;
    padding: 14px 16px !important; border-bottom: 1px solid #f2f2f2 !important; position: relative !important; display: block !important;
}
.xt-text-topNav::before {
    content: ""; position: absolute; left: 16px; top: 14px; width: 24px; height: 24px;
    background: url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23333333%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolyline%20points%3D%2215%2018%209%2012%2015%206%22%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;
}
.xt-text-topNav::after {
    content: ""; position: absolute; right: 16px; top: 14px; width: 56px; height: 24px;
    background-image: 
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23333333%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%2211%22%20cy%3D%2211%22%20r%3D%227%22%2F%3E%3Cline%20x1%3D%2221%22%20y1%3D%2221%22%20x2%3D%2216.65%22%20y2%3D%2216.65%22%2F%3E%3C%2Fsvg%3E"), 
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23333333%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2212%22%20r%3D%221.5%22%2F%3E%3Ccircle%20cx%3D%2219%22%20cy%3D%2212%22%20r%3D%221.5%22%2F%3E%3Ccircle%20cx%3D%225%22%20cy%3D%2212%22%20r%3D%221.5%22%2F%3E%3C%2Fsvg%3E");
    background-position: left center, right center;
    background-size: 20px 20px, 24px 24px;
    background-repeat: no-repeat;
}

/* --- 3. 正文区域 (优化名字上移) --- */
.xt-header { padding: 16px 16px 0 !important; display: flex !important; align-items: center !important; gap: 12px !important; background: #fff !important; margin: 0 !important; }
.xt-avatar { width: 44px !important; height: 44px !important; border-radius: 50% !important; border: none !important; object-fit: cover !important;}

/* 【核心突破】名字整体向上平移 5px，使其更贴近头像上缘 */
.xt-name { 
    color: #eb7340 !important; font-size: 16px !important; font-weight: 600 !important; 
    display: inline-flex !important; align-items: center !important; 
    transform: translateY(-5px) !important; 
}
.xt-name::after {
    content: "" !important; display: inline-block !important; width: 44px !important; height: 16px !important;
    background: url("https://i.postimg.cc/vZg0xw3r/IMG-4105.png") left center / contain no-repeat !important; margin-left: 6px !important; vertical-align: middle !important;
}

/* 时间标签同步向上收紧，间距更完美 */
.xt-text-postMeta { font-size: 12px !important; color: #939393 !important; margin: -20px 0 12px 72px !important; display: block !important; position: relative !important; }
.xt-text-postMeta::after {
    content: ""; position: absolute; right: 16px; top: -14px; width: 20px; height: 20px;
    background: url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23939393%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpolygon%20points%3D%2212%202%2015.09%208.26%2022%209.27%2017%2014.14%2018.18%2021.02%2012%2017.77%205.82%2021.02%207%2014.14%202%209.27%208.91%208.26%2012%202%22%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;
}

.xt-text-postText { font-size: 17px !important; color: #333 !important; line-height: 1.5 !important; padding: 0 16px !important; display: block !important; white-space: pre-wrap !important; }
.xt-text-postText + .xt-text-translateBtn { color: #617cb7 !important; font-size: 14px !important; display: block !important; padding: 10px 16px 16px 16px !important; }
.xt-spacer { height: 10px !important; background: #f2f2f2 !important; margin: 0 !important; border: none !important; }

/* --- 4. 互动 Tab 栏 --- */
.xt-row {
    display: flex !important; justify-content: flex-start !important; align-items: center !important;
    padding: 12px 16px 0 !important; border-bottom: 1px solid #e8e8e8 !important; margin: 0 !important; background: #fff !important;
}
.xt-row .xt-text-tabRepost { flex: 0 0 auto !important; font-size: 15px !important; color: #939393 !important; padding-bottom: 12px !important; margin-right: 16px !important; }
.xt-row .xt-text-tabComments {
    flex: 0 0 auto !important; font-size: 15px !important; color: #333 !important; font-weight: 700 !important; 
    padding-bottom: 12px !important; position: relative !important; margin-right: auto !important; 
}
.xt-row .xt-text-tabComments::after {
    content: ""; position: absolute; left: 50%; bottom: 0; transform: translateX(-50%); width: 28px; height: 3px; background: #eb7340; border-radius: 2px;
}
.xt-row .xt-text-tabLikes { flex: 0 0 auto !important; font-size: 15px !important; color: #939393 !important; padding-bottom: 12px !important; }

.xt-text-filterText { text-align: right !important; font-size: 12px !important; color: #617cb7 !important; padding: 6px 16px 0 !important; display: block !important; margin-bottom: -6px !important; position: relative; z-index: 2; }
.xt-text-filterText::before {
    content: ""; display: inline-block; width: 14px; height: 14px; vertical-align: middle; margin-right: 4px; margin-top: -2px;
    background: url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23617cb7%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cline%20x1%3D%2211%22%20y1%3D%226%22%20x2%3D%2221%22%20y2%3D%226%22%2F%3E%3Cline%20x1%3D%2211%22%20y1%3D%2212%22%20x2%3D%2219%22%20y2%3D%2212%22%2F%3E%3Cline%20x1%3D%2211%22%20y1%3D%2218%22%20x2%3D%2216%22%20y2%3D%2218%22%2F%3E%3Cline%20x1%3D%226%22%20y1%3D%2220%22%20x2%3D%226%22%20y2%3D%224%22%2F%3E%3Cpolyline%20points%3D%223%207%206%204%209%207%22%2F%3E%3C%2Fsvg%3E") center/contain no-repeat;
}

/* --- 5. 评论区引擎 (优化头像大小及排版缩进) --- */
.xt-text-comment1Name, .xt-text-comment2Name { 
    font-size: 14px !important; font-weight: 600 !important; color: #eb7340 !important; 
    padding: 16px 16px 4px 62px !important; /* 缩进配合头像放大 */
    position: relative !important; display: block !important; 
}
.xt-text-comment2Name { border-top: 1px solid #f2f2f2 !important; }

/* 【核心突破】评论头像由 32px 放大至 36px */
.xt-text-comment1Name::before { 
    content: ""; position: absolute; left: 16px; top: 16px; 
    width: 36px; height: 36px; 
    border-radius: 50%; background: url("https://i.postimg.cc/WpSVX0jr/IMG-3414.jpg") center/cover no-repeat; 
}
.xt-text-comment1Name::after { content: ""; display: inline-block; width: 36px; height: 14px; background: url("https://i.postimg.cc/0jXCrVSp/IMG-4106.png") left center / contain no-repeat; margin-left: 4px; vertical-align: middle; }

.xt-text-comment2Name::before { 
    content: ""; position: absolute; left: 16px; top: 16px; 
    width: 36px; height: 36px; 
    border-radius: 50%; background: url("https://i.postimg.cc/9f3Hrpt4/IMG-3027.jpg") center/cover no-repeat; 
}

.xt-text-comment1Text, .xt-text-comment2Text { 
    font-size: 15px !important; color: #333 !important; line-height: 1.4 !important; 
    padding: 0 16px 4px 62px !important; /* 同步缩进 */
    display: block !important; white-space: pre-wrap !important; 
}

/* 【核心突破】强制评论区翻译键变蓝 */
.xt-text-comment1Text + .xt-text-translateBtn, .xt-text-comment2Text + .xt-text-translateBtn { 
    color: #617cb7 !important; /* 修复为微博专属蓝 */
    font-size: 13px !important; 
    padding: 0 16px 12px 62px !important; /* 同步缩进 */
    display: block !important;
}

/* 评论底部信息 */
.xt-text-comment1Meta, .xt-text-comment2Meta { 
    font-size: 12px !important; color: #939393 !important; 
    padding: 0 0 16px 62px !important; /* 同步缩进 */
    display: inline-block !important; 
}
.xt-text-comment1Likes, .xt-text-comment2Likes { 
    float: right !important; font-size: 13px !important; color: #939393 !important; 
    padding: 0 16px 16px 0 !important; display: flex !important; align-items: center !important; 
}

/* 评论区原版极细 SVG 图标 */
.xt-text-comment1Likes::before, .xt-text-comment2Likes::before {
    content: ""; display: inline-block; width: 85px; height: 16px; margin-right: 6px;
    background-image: 
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23939393%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M18%2013v6a2%202%200%200%201-2%202H5a2%202%200%200%201-2-2V8a2%202%200%200%201%202-2h6%22%2F%3E%3Cpolyline%20points%3D%2215%203%2021%203%2021%209%22%2F%3E%3Cline%20x1%3D%2210%22%20y1%3D%2214%22%20x2%3D%2221%22%20y2%3D%223%22%2F%3E%3C%2Fsvg%3E"),
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23939393%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M21%2015a2%202%200%200%201-2%202H7l-4%204V5a2%202%200%200%201%202-2h14a2%202%200%200%201%202%202z%22%2F%3E%3Cline%20x1%3D%228%22%20y1%3D%2210%22%20x2%3D%228.01%22%20y2%3D%2210%22%20stroke-width%3D%222%22%2F%3E%3Cline%20x1%3D%2212%22%20y1%3D%2210%22%20x2%3D%2212.01%22%20y2%3D%2210%22%20stroke-width%3D%222%22%2F%3E%3Cline%20x1%3D%2216%22%20y1%3D%2210%22%20x2%3D%2216.01%22%20y2%3D%2210%22%20stroke-width%3D%222%22%2F%3E%3C%2Fsvg%3E"),
        url("data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23939393%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M14%209V5a3%203%200%200%200-3-3l-4%209v11h11.28a2%202%200%200%200%202-1.7l1.38-9a2%202%200%200%200-2-2.3zM7%2022H4a2%202%200%200%201-2-2v-7a2%202%200%200%201%202-2h3%22%2F%3E%3C%2Fsvg%3E");
    background-position: left center, center center, right center;
    background-size: 15px 15px;
    background-repeat: no-repeat;
}

