}

/* ─── 翻页魔法 ─── */
.xt-divider { display: none !important; }
.xt-divider ~ * { display: none; }
#xt-t1:checked ~ .xt-content > *:not(.xt-divider ~ *):not(.xt-action-1) { display: none; }
#xt-t1:checked ~ .xt-content > .xt-divider ~ * { display: block; animation: xt-fadeInUp 0.5s ease; }
#xt-t1:checked ~ .xt-content > .xt-row.xt-divider ~ * { display: flex; }

/* ─── 侧边丝带书签 ─── */
.xt-action-1 {
  display: block; position: absolute;
  top: 20px; right: -8px;
  background: #e8b4b8; color: #fff;
  padding: 12px 8px; border-radius: 8px 0 0 8px;
  font-size: 12px; writing-mode: vertical-rl; letter-spacing: 2px;
  box-shadow: -2px 2px 8px rgba(232, 180, 184, 0.4);
  cursor: pointer; z-index: 10; transition: 0.3s;
}
.xt-action-1::after { content: "翻页 ✦ 饲养指南"; }
#xt-t1:checked ~ .xt-content .xt-action-1 { background: #d79ca0; }
