/* ─── 优雅的标题装饰 ─── */
.xt-card-title::before { content: "✦ "; color: #e8b4b8; font-size: 12px; }
.xt-section-title::before { content: "✦ "; color: #e8b4b8; font-size: 12px; }
.xt-collapse-header::before { content: "✦ "; color: #e8b4b8; font-size: 12px; }

/* ─── 1. 圆形头像 & Q弹云朵气泡 (完美对齐) ─── */
@keyframes floatBubble {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}
.xt-header { 
  justify-content: flex-start; padding-left: 5px; position: relative; margin-bottom: 35px; 
}
/* 恢复优雅的圆形头像，带淡淡的光晕 */
.xt-avatar { 
  border-radius: 50%; border: 2px solid #e8b4b8; 
  box-shadow: 0 4px 10px rgba(232, 180, 184, 0.3); 
  z-index: 2; position: relative; width: 48px; height: 48px; 
}
.xt-name { 
  font-family: 'Noto Serif SC', serif; font-size: 16px; 
  color: #7a6366; margin-left: 12px; font-weight: bold; 
}

