.xt-text-secretThought {
  position: absolute; 
  top: 8px; 
  left: 90px; /* 往右移，距离刚刚好 */
  background: #fff; border: 2px solid #f2d8d9; border-radius: 50% / 40%;
  padding: 6px 12px; color: #d79ca0; font-weight: bold; font-size: 12px;
  box-shadow: 0 4px 10px rgba(232, 180, 184, 0.15); z-index: 10; max-width: 180px;
  animation: floatBubble 2.5s ease-in-out infinite; 
}
/* 重新计算的引流小圆圈，完美指向圆形头像 */
.xt-text-secretThought::after {
  content: ""; position: absolute; top: 12px; left: -14px;
  width: 8px; height: 8px; background: #fff; border: 2px solid #f2d8d9; border-radius: 50%;
}
.xt-text-secretThought::before {
  content: ""; position: absolute; top: 20px; left: -24px;
  width: 5px; height: 5px; background: #fff; border: 2px solid #f2d8d9; border-radius: 50%;
}

